<?php
declare(strict_types=1);require_once __DIR__.'/auth_check.php';require_once __DIR__.'/bootstrap.php';$pdo=app_database();if(!isset($_SESSION['admin_chat_csrf']))$_SESSION['admin_chat_csrf']=bin2hex(random_bytes(24));$conversations=$pdo->query("SELECT c.*,p.designation,(SELECT message FROM messages_boutique m WHERE m.conversation_id=c.id ORDER BY m.id DESC LIMIT 1) dernier_message,(SELECT COUNT(*) FROM messages_boutique m WHERE m.conversation_id=c.id AND m.expediteur='visiteur' AND m.lu_at IS NULL) non_lus FROM conversations_boutique c LEFT JOIN produit p ON p.id_produit=c.produit_id ORDER BY c.updated_at DESC")->fetchAll(PDO::FETCH_ASSOC);function mch(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages boutique | FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><style>.messaging-shell{display:grid;grid-template-columns:340px 1fr;height:680px;overflow:hidden;background:#fff;border:1px solid var(--brand-border);border-radius:22px;box-shadow:0 15px 40px rgba(34,37,75,.08)}.conversation-list{overflow:auto;border-right:1px solid var(--brand-border)}.conversation-list h2{position:sticky;top:0;z-index:2;margin:0;padding:18px;background:#fff;color:var(--brand-primary);font:800 1rem var(--brand-font-heading)}.conversation-item{display:block;width:100%;padding:14px 16px;color:inherit;background:#fff;border:0;border-top:1px solid #eeeef3;text-align:left}.conversation-item.active,.conversation-item:hover{background:#f3f3f8}.conversation-item strong,.conversation-item small,.conversation-item span{display:block}.conversation-item span{overflow:hidden;color:var(--brand-text-muted);font-size:.7rem;text-overflow:ellipsis;white-space:nowrap}.conversation-item small{margin-top:5px;color:#999;font-size:.62rem}.conversation-item b{float:right;display:grid;min-width:20px;height:20px;place-items:center;color:#fff;background:#b6404a;border-radius:50%;font-size:.6rem}.admin-chat{display:flex;min-width:0;flex-direction:column}.admin-chat-head{padding:17px 20px;color:#fff;background:var(--brand-primary)}.admin-chat-head strong,.admin-chat-head small{display:block}.admin-chat-head small{color:#ffffffad}.admin-chat-messages{display:flex;flex:1;flex-direction:column;gap:9px;padding:20px;overflow:auto;background:#f6f6f9}.admin-message{max-width:75%;padding:10px 12px;border-radius:13px;font-size:.78rem}.admin-message.visiteur{align-self:flex-start;background:#fff}.admin-message.utilisateur{align-self:flex-end;color:var(--brand-primary);background:var(--brand-accent)}.admin-message small{display:block;margin-top:4px;opacity:.65;font-size:.58rem}.admin-compose{display:grid;grid-template-columns:1fr 48px;gap:8px;padding:13px;border-top:1px solid var(--brand-border)}.admin-compose textarea{padding:11px;resize:none;border:1px solid var(--brand-border);border-radius:11px}.admin-compose button{color:var(--brand-primary);background:var(--brand-accent);border:0;border-radius:11px}.chat-placeholder{display:grid;flex:1;place-content:center;text-align:center;color:var(--brand-text-muted)}@media(max-width:750px){.messaging-shell{grid-template-columns:110px 1fr}.conversation-item span,.conversation-item small{display:none}.conversation-list h2{font-size:.72rem}.admin-chat-messages{padding:12px}.admin-message{max-width:90%}}</style></head><body class="module-page messaging-page"><?php include __DIR__.'/partials/navbar.php';?><main class="container"><div class="module-heading"><div class="module-heading__copy"><span class="module-heading__icon"><i class="fa-solid fa-comments"></i></span><div><h1>Messages boutique</h1><p>Répondez en direct aux visiteurs et conseillez-les avant leur commande.</p></div></div></div><section class="messaging-shell"><aside class="conversation-list"><h2>Conversations</h2><?php foreach($conversations as$c):?><button class="conversation-item" data-conversation="<?=$c['id']?>" data-name="<?=mch($c['nom_visiteur']?:'Visiteur')?>" data-product="<?=mch($c['designation']?:'Discussion générale')?>"><?php if($c['non_lus']):?><b><?=$c['non_lus']?></b><?php endif?><strong><?=mch($c['nom_visiteur']?:'Visiteur')?></strong><span><?=mch($c['dernier_message']?:'Nouvelle conversation')?></span><small><?=mch($c['designation']?:date('d/m/Y H:i',strtotime($c['updated_at'])))?></small></button><?php endforeach?></aside><section class="admin-chat"><header class="admin-chat-head" id="adminChatHead" hidden><strong id="adminChatName"></strong><small id="adminChatProduct"></small></header><div class="admin-chat-messages" id="adminChatMessages"><div class="chat-placeholder"><i class="fa-regular fa-comments fa-2x mb-2"></i>Sélectionnez une conversation.</div></div><form class="admin-compose" id="adminChatForm" hidden><textarea id="adminChatInput" rows="2" maxlength="1500" placeholder="Votre réponse…" required></textarea><button><i class="fa-solid fa-paper-plane"></i></button></form></section></section></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script><script>const csrf=<?=json_encode($_SESSION['admin_chat_csrf'])?>,messages=document.getElementById('adminChatMessages'),form=document.getElementById('adminChatForm'),input=document.getElementById('adminChatInput');let current=0,last='';const esc=v=>{const s=document.createElement('span');s.textContent=v;return s.innerHTML};async function load(){if(!current)return;const data=await fetch('request/chat_admin.php?conversation_id='+current,{cache:'no-store'}).then(r=>r.json()),sig=JSON.stringify(data.messages);if(sig===last)return;last=sig;messages.innerHTML=data.messages.map(m=>`<div class="admin-message ${m.expediteur}">${esc(m.message)}<small>${m.expediteur==='utilisateur'?(esc(m.agent.trim())||'FIDEST'):'Visiteur'} · ${new Date(m.created_at.replace(' ','T')).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('');messages.scrollTop=messages.scrollHeight}document.querySelectorAll('.conversation-item').forEach(b=>b.onclick=()=>{current=Number(b.dataset.conversation);last='';document.querySelectorAll('.conversation-item').forEach(x=>x.classList.toggle('active',x===b));b.querySelector('b')?.remove();document.getElementById('adminChatName').textContent=b.dataset.name;document.getElementById('adminChatProduct').textContent=b.dataset.product;document.getElementById('adminChatHead').hidden=false;form.hidden=false;load()});form.onsubmit=async e=>{e.preventDefault();const message=input.value.trim();if(!message)return;input.value='';await fetch('request/chat_admin.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csrf,conversation_id:current,message})});last='';load()};setInterval(load,3000);</script></body></html>
